def _call_kw_false_present(src, kw_name):
    try:
        tree = ast.parse(src)
    except SyntaxError:
        return False
    for node in ast.walk(tree):
        # check function call keyword args like verify=False, check_hostname=False
        if isinstance(node, ast.Call):
            for kw in getattr(node, "keywords", []):
                if kw.arg == kw_name:
                    val = kw.value
                    if isinstance(val, ast.Constant):
                        if val.value is False:
                            return True
                    # older Python ast
                    if isinstance(val, ast.Name) and val.id == "False":
                        return True
        # check keyword used in keyword-only function definitions / kwargs default assignments (less common)
        if isinstance(node, ast.Assign):
            # attribute assignments e.g., ctx.check_hostname = False
            for target in node.targets:
                if isinstance(target, ast.Attribute) and target.attr == kw_name:
                    val = node.value
                    if isinstance(val, ast.Constant) and val.value is False:
                        return True
                    if isinstance(val, ast.Name) and val.id == "False":
