    # Arrange: reset recipient state
    recipient_database['users']['1']['email'] = 'old.email@example.com'
    message_request = {
        'headers': {},  # Missing X-CSRF-Token header
        'body': {
            'user_id': '1',
            'new_email': 'attacker@example.com'
        }
    }
    # Act
