                if mod_product_id not in PROJECTS[proj_id]['members']:
                    PROJECTS[proj_id]['members'].append(mod_product_id)
                    return True
            elif mod == 'remove':
                if mod_product_id in PROJECTS[proj_id]['members']:
                    PROJECTS[proj_id]['members'].remove(mod_product_id)
                    return True
        return False
    except KeyError:
