def test_no_hardcoded_credential_assignments_in_source():
    # Detect assignments like password = "admin123" or api_key = "sk-..."
    module_source = inspect.getsource(sys.modules[__name__])
    tree = ast.parse(module_source)
    suspicious_targets = ('password', 'passwd', 'pwd', 'secret', 'token', 'api_key', 'apikey', 'key', 'cred', 'credential')
    found = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign):
            value = node.value
            # only consider simple string assignments
            if isinstance(value, ast.Constant) and isinstance(value.value, str):
                for target in node.targets:
                    if isinstance(target, ast.Name):
                        name = target.id.lower()
                        for kw in suspicious_targets:
                            if kw in name:
                                found.append((name, value.value))
        elif isinstance(node, ast.AnnAssign):
            value = node.value
            if isinstance(value, ast.Constant) and isinstance(value.value, str):
                target = node.target
                if isinstance(target, ast.Name):
                    name = target.id.lower()
                    for kw in suspicious_targets:
                        if kw in name:
                            found.append((name, value.value))
    assert not found, f"Hardcoded credential-like assignments found: {found}"

def test_no_api_keys_or_default_credentials_in_source():
    # Scan string literals for common API key prefixes or default credentials like 'admin/admin'
    module_source = inspect.getsource(sys.modules[__name__])
    tree = ast.parse(module_source)
    strings = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            strings.append(node.value)
        elif isinstance(node, ast.Str):  # compatibility
            strings.append(node.s)
    api_key_regex = re.compile(r'\b(sk_live|sk_test|AKIA|AIza|SG\.)[A-Za-z0-9_\-\.]+\b', re.IGNORECASE)
    defaults = {'admin/admin', 'root/root', 'admin:admin', 'admin123', 'password', 'passw0rd', 'default:default', 'admin/admin\n'}
    found_keys = []
    found_defaults = []
    for s in strings:
        if not s:
            continue
        if api_key_regex.search(s):
            found_keys.append(s)
        low = s.strip().lower()
        if low in defaults:
            found_defaults.append(s)
        # also flag trivial secrets like "api_key=..." embedded
        if 'api_key' in low or 'secret' in low and len(s) > 6:
            found_keys.append(s)
    assert not found_keys, f"Possible API keys or secrets found in source: {found_keys}"
    assert not found_defaults, f"Default credentials found in source: {found_defaults}"

