                if kw.arg == "verify":
                    verify_found = True
                    # Handle different AST types for boolean constants across versions
                    if isinstance(kw.value, ast.Constant):
                        if kw.value.value is True:
                            verify_true = True
                    elif isinstance(kw.value, ast.NameConstant):  # Python <3.8
                        if kw.value.value is True:
