    key = RSA_mod.import_key(pem)
    # Direct check that generated/exported key is not using deprecated 1024-bit size
    assert key.size() != 1024, "RSA key must not be 1024 bits (deprecated and insecure)"
    # Enforce modern minimum
    assert key.size() >= 2048, "RSA key size is inadequate; must be >= 2048 bits"


def test_no_weak_randfunc_or_small_constants_in_source():
    src = inspect.getsource(init_ssh_identity_key)
    tree = ast.parse(src)

    class RSAGenerateVisitor(ast.NodeVisitor):
        def __init__(self):
            self.small_constant_used = False
            self.randfunc_uses_weak = False

        def visit_Call(self, node):
            # detect calls like RSA.generate(...)
            func = node.func
            is_rsa_generate = False
            if isinstance(func, ast.Attribute):
                if getattr(func.attr, 'lower', lambda: '')() == 'generate':
                    # check if the value is Name RSA
                    if isinstance(func.value, ast.Name) and func.value.id == 'RSA':
                        is_rsa_generate = True
            if is_rsa_generate:
                # check positional args for small integer constants
                for arg in node.args:
                    if isinstance(arg, ast.Constant) and isinstance(arg.value, int):
                        if arg.value < 2048:
                            self.small_constant_used = True
                # check keywords for bits= or randfunc= usage
                for kw in node.keywords:
                    if kw.arg in ('bits', 'nbits') and isinstance(kw.value, ast.Constant) and isinstance(kw.value.value, int):
                        if kw.value.value < 2048:
                            self.small_constant_used = True
                    if kw.arg == 'randfunc':
                        # shallow detection: if randfunc references 'random' module names mark as weak
                        names = [n.id for n in ast.walk(kw.value) if isinstance(n, ast.Name)]
                        attrs = [n.attr for n in ast.walk(kw.value) if isinstance(n, ast.Attribute)]
                        combined = set(names + attrs)
                        # weak if random.* or insecure PRNG names used
                        if 'random' in combined or 'randint' in combined or 'randomrandom' in combined:
                            self.randfunc_uses_weak = True
            self.generic_visit(node)

    visitor = RSAGenerateVisitor()
    visitor.visit(tree)

    # Assertions: secure code must not use small literal constants nor weak randfuncs
    assert not visitor.small_constant_used, "Source uses RSA.generate with <2048 bit literal"
    assert not visitor.randfunc_uses_weak, "Source passes a weak randfunc (uses random.*) for RSA.generate"

