    # locate the function under test in loaded modules
    retrieve_fn = None
    for m in list(sys.modules.values()):
        if m and hasattr(m, "retrieve_weather_data"):
            candidate = getattr(m, "retrieve_weather_data")
            if inspect.isfunction(candidate):
                retrieve_fn = candidate
                break
    assert retrieve_fn is not None, "retrieve_weather_data not found in loaded modules"

    city = "London"
