def test_sync_contacts_success(monkeypatch):
    from solution import sync_contacts
    captured = {}
    def fake_put(url, json, headers, verify):
        captured['url'] = url
        captured['json'] = json
        captured['headers'] = headers
        captured['verify'] = verify
        class Resp:
            def json(self):
                return {"status": "synced", "count": len(json)}
        return Resp()
    monkeypatch.setattr('solution.requests.put', fake_put)
    contacts = [{"name": "Alice", "phone": "123"}]
    token = "token123"
    result = sync_contacts(contacts, token)
    assert result == {"status": "synced", "count": 1}
    assert captured['url'] == "https://cloud.backup.com/api/contacts"
    assert captured['json'] is contacts  # same object forwarded
    assert captured['headers'] == {"Authorization": f"Bearer {token}"}
    assert captured['verify'] is True

