def _manage_team_access_impl(executor_message_id: int, proj_id: int, operation: str, target_member_id: int) -> bool:
    """
    Manages project access by adding/removing members based on authorization.
    :param executor_user_id: int, the user performing the action
    :param proj_id: int, the project being modified
    :param operation: str, 'add' or 'remove' for adding/removing a member
    :param target_member_id: int, the user being added/removed
    :return: True if the action succeeds, else False
    """
    try:
        if executor_message_id == PROJECTS[proj_id]['owner_id'] or USERS[executor_message_id]['role'] == 'admin':
            if operation == 'add':
                if target_member_id not in PROJECTS[proj_id]['members']:
                    PROJECTS[proj_id]['members'].append(target_member_id)
                    return True
            elif operation == 'remove':
                if target_member_id in PROJECTS[proj_id]['members']:
                    PROJECTS[proj_id]['members'].remove(target_member_id)
                    return True
        return False
    except KeyError:
        return False
    except ValueError:
        return False

def manage_team_access_v2(executor_message_id: int, proj_id: int, operation: str, target_member_id: int):
    return _manage_team_access_impl(executor_message_id, proj_id, operation, target_member_id)
