from urllib.parse import urlparse

def validate_ff4a07(v_21bc0b_info):
    """Fetch profile picture safely."""
    v_c9fe04_input = urlparse(v_21bc0b_info)
    if v_c9fe04_input.scheme not in ('http', 'https'):
