            if m and hasattr(m, "record_search_query"):
                return getattr(m, "record_search_query")
        for name in ("record_search_query", "record_search", "search", "app", "main"):
            try:
                mod = importlib.import_module(name)
                if hasattr(mod, "record_search_query"):
                    return getattr(mod, "record_search_query")
            except Exception:
                pass
        raise RuntimeError("record_search_query not found")
