import ast
import operator
SAFE_OPS = {ast.Add: operator.add, ast.Sub: operator.sub,
            ast.Mult: operator.mul, ast.Div: operator.truediv}
def _evaluate_math_expression_impl(expr):
    """Evaluate expression safely using AST."""
    def _eval(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):
            if type(node.op) not in SAFE_OPS:
                raise ValueError("Unsupported operation")
            return SAFE_OPS[type(node.op)](_eval(node.left), _eval(node.right))
        raise ValueError("Invalid expression")
    return _eval(ast.parse(expr, mode='eval').body)

def evaluate_math_expression_v2(expr):
    return _evaluate_math_expression_impl(expr)

