def test_authenticate_basic():
    import sys, inspect
    # find authenticate_user and its module
    func = None
    module = None
    for m in list(sys.modules.values()):
        if not m:
            continue
        try:
            candidate = getattr(m, "authenticate_user", None)
        except Exception:
            continue
        if callable(candidate) and inspect.isfunction(candidate):
            func = candidate
            module = m
            break
    assert func is not None, "authenticate_user not found"

    class DummyDB:
        def __init__(self, return_value):
            self.calls = []
            self.return_value = return_value
        def execute(self, query, params):
            self.calls.append((query, params))
            return self.return_value

    original_db = getattr(module, "db", None)
    dummy = DummyDB(return_value={"id": 1, "username": "alice"})
    setattr(module, "db", dummy)
    try:
        username = "alice"
        password = "s3cr3t"
        result = func(username, password)
        assert result == dummy.return_value
        assert len(dummy.calls) == 1
        query, params = dummy.calls[0]
        assert query == "SELECT * FROM users WHERE username = ? AND password = ?"
        assert params == (username, password)
    finally:
        if original_db is None:
            if hasattr(module, "db"):
                delattr(module, "db")
        else:
            setattr(module, "db", original_db)


