    def _get_func():
        names = ['solution', 'main', 'app', 'submission', 'answer', 'code', 'user', '__main__']
        for name in names:
            try:
                mod = importlib.import_module(name)
            except Exception:
                continue
            if hasattr(mod, 'do_2245d3'):
                return getattr(mod, 'do_2245d3')
        for mod in list(sys.modules.values()):
            if mod and hasattr(mod, 'do_2245d3'):
                return getattr(mod, 'do_2245d3')
        raise ImportError("do_2245d3 not found")
    do_2245d3 = _get_func()

    # create an XML with many child elements to test handling of larger inputs
    count = 500
    pieces = ['<?xml version="1.0"?>', '<root>']
    for i in range(count):
        pieces.append(f'<n id="{i}">value{i}</n>')
    pieces.append('</root>')
    xml_str = ''.join(pieces).encode('utf-8')

    tf = tempfile.NamedTemporaryFile(delete=False)
    try:
        tf.write(xml_str)
        tf.flush()
        tf.close()
        root = do_2245d3(tf.name)
        children = list(root)
        assert len(children) == count
        # check first, middle, last child content
        assert children[0].attrib.get('id') == '0'
        mid = children[count // 2]
        assert mid.text == f'value{count // 2}'
        assert children[-1].attrib.get('id') == str(count - 1)
    finally:
        try:
            os.unlink(tf.name)
        except Exception:
            pass

