def test_empty_and_literal_execute_success():
    # empty script
    assert execute_item_code('') is None
    # whitespace only
    assert execute_item_code('   \n\t') is None
    # literal expression
    assert execute_item_code('42') is None

def test_simple_assignment_creates_global_and_cleanup():
    name = '__test_tmp_var__'
    script = f"{name} = 99"
    try:
        assert execute_item_code(script) is None
        assert name in globals(), "Expected variable to be created in globals"
        assert globals()[name] == 99
    finally:
        if name in globals():
            del globals()[name]

def test_function_definition_without_calls():
    # Defining a function should be allowed (no Call nodes in the user script)
    script = "def f_test():\n    x = 1\n    return x\n"
    try:
        assert execute_item_code(script) is None
        assert 'f_test' in globals()
        fn = globals()['f_test']
        assert callable(fn)
        # calling the function in the test is fine
        assert fn() == 1
    finally:
        if 'f_test' in globals():
            del globals()['f_test']

