def _assert_raises_value_error_with_messages(script, *expected_substrings):
    try:
        execute_item_code(script)
    except ValueError as e:
        msg = str(e)
        assert 'Invalid or dangerous script:' in msg
        for sub in expected_substrings:
            assert sub in msg, f"Expected substring {sub!r} in error message {msg!r}"
    else:
        assert False, "Expected ValueError to be raised"

