def test_process_upload_v2_exact_max_size():
    # Avoid allocating MAX_SIZE bytes by returning an object that reports the correct length
    class LargeFake:
        def __init__(self, length):
            self._length = length
        def __len__(self):
            return self._length
        def __repr__(self):
            return f"<LargeFake length={self._length}>"

    class Reader:
        def __init__(self, ret):
            self.ret = ret
            self.called_with = None
        def read(self, n):
            # ensure the function requests MAX_SIZE + 1
            self.called_with = n
            return self.ret

    fake = LargeFake(MAX_SIZE)
    reader = Reader(fake)
    result = process_upload_v2(reader)
    assert reader.called_with == MAX_SIZE + 1
    assert result is fake
    assert len(result) == MAX_SIZE

def test_process_upload_v2_one_byte_over_raises():
