    weak_funcs = {
        'random', 'randint', 'randrange', 'randbytes', 'randomize',
        'choice', 'choices', 'shuffle', 'sample', 'uniform', 'betavariate',
        'expovariate', 'vonmisesvariate', 'weibullvariate', 'triangular'
    }
    detections = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name == 'random':
                    detections.append(('import', 'random'))
        elif isinstance(node, ast.ImportFrom):
            if node.module == 'random':
                detections.append(('from', 'random'))
            else:
                for alias in node.names:
                    if alias.name in weak_funcs and node.module is None:
                        detections.append(('importfrom_weakname', alias.name))
        elif isinstance(node, ast.Call):
            funcnode = node.func
            if isinstance(funcnode, ast.Name) and funcnode.id in weak_funcs:
                detections.append(('call', funcnode.id))
            elif isinstance(funcnode, ast.Attribute):
                # e.g., random.randint or some_alias.randint
                if isinstance(funcnode.value, ast.Name) and funcnode.value.id == 'random' and funcnode.attr in weak_funcs:
                    detections.append(('attr_call', f"random.{funcnode.attr}"))
