def _collect_requests_calls_module_ast(module_source):
    tree = ast.parse(module_source)
    calls = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            func = node.func
            if isinstance(func, ast.Attribute) and isinstance(func.value, ast.Name):
                if func.value.id == 'requests' and func.attr in {'get','request','post','head','put','delete','options'}:
                    calls.append(node)
    return calls

