    # Return True if keyword value is a literal True, False otherwise
    val = kw.value
    # ast.Constant covers True/False in modern Python
    if isinstance(val, ast.Constant):
        return val.value is True
    # older AST node for booleans
    if hasattr(ast, 'NameConstant') and isinstance(val, ast.NameConstant):
        return val.value is True
    return False  # non-constant -> treat as not strictly True

