import sys
import inspect
import logging

def _find_target():
    for m in list(sys.modules.values()):
        if not m:
            continue
        try:
            candidate = getattr(m, "log_document_activity", None)
        except Exception:
            continue
        if callable(candidate):
            return candidate
    raise RuntimeError("log_document_activity not found in loaded modules")

def _sanitize_preview(s):
    return s.replace("\n", " ").replace("\r", " ")

def test_log_sanitizes_newlines(caplog):
    func = _find_target()
    logger_name = func.__module__ if hasattr(func, "__module__") else None
    if logger_name:
        caplog.set_level(logging.INFO, logger=logger_name)
    # input containing newline attempts to inject forged log lines
    doc_name = "document1\nATTACKER_LINE"
    action = "delete\nFORGED: CRITICAL"
    func(doc_name, action)
    # ensure a log record was emitted
    assert len(caplog.records) >= 1
    # inspect the last record emitted by the module's logger
    msg = caplog.records[-1].getMessage()
    # there must be no raw newline or carriage return characters in the logged message
    assert "\n" not in msg and "\r" not in msg
    # the logged string should match the expected sanitized output
    expected_doc = _sanitize_preview(doc_name)
    expected_action = _sanitize_preview(action)
    assert msg == f"User {expected_doc} performed {expected_action}"

