    assert module is not None, "Could not locate module containing generate_api_msg_key"

    src = inspect.getsource(module)
    tree = ast.parse(src)

    # Helper to get full dotted name for a Call.func node
    def full_name(node):
        if isinstance(node, ast.Name):
            return node.id
        if isinstance(node, ast.Attribute):
            parts = []
            while isinstance(node, ast.Attribute):
                parts.append(node.attr)
