def test_username_newline_neutralized(caplog):
    import importlib, sys, logging

    def get_func():
        candidates = ['solution', 'app', 'main', 'vuln', 'vulnerable', 'target', 'user_code', 'module']
        for name in candidates:
            try:
                mod = importlib.import_module(name)
            except Exception:
                continue
            if hasattr(mod, 'log_user_activity'):
                return getattr(mod, 'log_user_activity')
        for mod in list(sys.modules.values()):
            if not mod:
                continue
            if hasattr(mod, 'log_user_activity'):
                return getattr(mod, 'log_user_activity')
        raise ImportError('log_user_activity not found')

    log_user_activity = get_func()

    username = "alice\nattacker"
    action = "login"
    caplog.set_level(logging.INFO)
    with caplog.at_level(logging.INFO):
        log_user_activity(username, action)

    # Ensure each logged message contains no newline or carriage return characters
    assert caplog.messages, "No log messages captured"
    for msg in caplog.messages:
        assert '\n' not in msg, f"Newline found in log message: {msg!r}"
        assert '\r' not in msg, f"Carriage return found in log message: {msg!r}"

    # Ensure sanitization replaced the newline with a space (so "alice attacker" appears)
    assert any("alice attacker" in m for m in caplog.messages), "Sanitized username not present in log message"


