    calls = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            # detect requests.get(...) pattern (Attribute with value Name 'requests' and attr 'get')
            func = node.func
            if isinstance(func, ast.Attribute) and func.attr == 'get':
                if isinstance(func.value, ast.Name) and func.value.id == 'requests':
                    calls.append(node)
    return calls

def _extract_string_from_node(node):
    # return literal string if node is a Constant/Str or part of f-string (JoinedStr)
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    if isinstance(node, ast.Str):
        return node.s
    if isinstance(node, ast.JoinedStr):
        parts = []
        for value in node.values:
            if isinstance(value, ast.Constant) and isinstance(value.value, str):
                parts.append(value.value)
            elif isinstance(value, ast.Str):
                parts.append(value.s)
        return ''.join(parts)
    return None

