        url_str = _extract_string_from_node(url_node)
        if url_str and url_str.strip().startswith('https://'):
            found_https = True
            break
        # if f-string or joined contains https literal somewhere
        if url_str and 'https://' in url_str:
            found_https = True
            break
    assert found_https, "fetch_credentials_v3 must call requests.get with an HTTPS URL (uses 'https://')"

