def test_add_private_key_refuses_plain_private_key_on_import():
    import sys, inspect, pytest
    from Crypto.PublicKey import RSA

    # Locate add_private_key in loaded modules
    add_private_key = None
    for mod in list(sys.modules.values()):
        if not mod:
            continue
        if hasattr(mod, "add_private_key"):
            candidate = getattr(mod, "add_private_key")
            if inspect.isfunction(candidate):
                add_private_key = candidate
                break
    if add_private_key is None:
        pytest.skip("add_private_key not found in loaded modules")

    pem = add_private_key()
    assert isinstance(pem, str), "add_private_key must return a string"

    # If the PEM is properly encrypted, importing without a passphrase should raise an error.
    try:
        RSA.import_key(pem)  # should raise for encrypted private keys
    except Exception:
        # An exception indicates the private key is protected (expected for secure implementations)
        return
    # If no exception, the private key was importable without a passphrase -> vulnerable
    pytest.fail("Private key is importable without a passphrase (likely unencrypted PEM)")

def test_add_private_key_contains_encryption_indicators():
    import sys, inspect, re, pytest

    # Locate add_private_key in loaded modules
    add_private_key = None
    for mod in list(sys.modules.values()):
        if not mod:
            continue
        if hasattr(mod, "add_private_key"):
