            if inspect.isfunction(candidate):
                add_private_key = candidate
                break
    if add_private_key is None:
        pytest.skip("add_private_key not found in loaded modules")

    pem = add_private_key()
    assert isinstance(pem, str), "add_private_key must return a string"

    # Look for common PEM encryption indicators:
    # - PKCS#8 encrypted PEM header
    # - Old-style PEM encryption markers (Proc-Type and DEK-Info)
    pattern = re.compile(
        r"-----BEGIN ENCRYPTED PRIVATE KEY-----|Proc-Type:\s*4,ENCRYPTED|DEK-Info:",
        re.IGNORECASE,
    )
    if pattern.search(pem):
        return  # Found encryption indicators => secure
    pytest.fail("No PEM encryption indicators found; private key appears unencrypted")

