    # Compatible check for ast.Constant(value=True) and ast.NameConstant(True)
    if isinstance(node, ast.Constant):
        return node.value is True
    if hasattr(ast, "NameConstant") and isinstance(node, ast.NameConstant):
        return node.value is True
    return False

