import inspect
import ast
import hashlib


def _detect_hash_algo(func):
    src = inspect.getsource(func)
    tree = ast.parse(src)

    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            f = node.func
            # direct calls like hashlib.sha256(...)
            if isinstance(f, ast.Attribute) and isinstance(f.value, ast.Name) and f.value.id == 'hashlib':
                if f.attr == 'new':
                    # attempt to read constant algorithm name
                    if node.args and isinstance(node.args[0], ast.Constant) and isinstance(node.args[0].value, str):
                        return ('new', node.args[0].value.lower())
                    return ('new', None)
                return ('attr', f.attr.lower())
            # patterns like (hashlib.sha256(...)).hexdigest() - inner call handled above by walk
    return (None, None)


def test_no_weak_algorithms():
    """
    Detect use of weak hashing algorithms (CWE-327). The test passes when a strong
    algorithm (SHA-2, SHA-3 or BLAKE2 family) is used and fails if a weak one
    (e.g., md5, sha1) is detected or the algorithm cannot be determined.
    """
    algo_type, algo_name = _detect_hash_algo(validate_d145ac)
    assert algo_type is not None, "No hashlib usage detected in validate_d145ac"

    allowed = {
        'sha224', 'sha256', 'sha384', 'sha512',
        'sha3_224', 'sha3_256', 'sha3_384', 'sha3_512',
        'blake2b', 'blake2s'
    }

    if algo_type == 'attr':
        assert algo_name in allowed, f"Weak or disallowed hash algorithm used: {algo_name}"
    elif algo_type == 'new':
        assert algo_name is not None, "hashlib.new used with non-constant algorithm name; cannot verify strength"
        assert algo_name in allowed, f"Weak or disallowed hash algorithm used via hashlib.new: {algo_name}"
    else:
        assert False, "Unable to determine hashing algorithm used in validate_d145ac"


def test_validate_d145ac_produces_expected_hexdigest():
    """
    Ensure validate_d145ac returns True when given the hexdigest produced by
    the detected hashing algorithm and False for an incorrect digest.
    This verifies the function actually computes a cryptographic hash digest
    consistent with hashlib usage.
    """
    algo_type, algo_name = _detect_hash_algo(validate_d145ac)
    assert algo_type is not None, "No hashlib usage detected in validate_d145ac"

    data = b"security-test-input-123"
    # compute expected digest using the detected algorithm
    if algo_type == 'attr':
        # prefer direct attribute; fallback to hashlib.new if attribute not present
        if hasattr(hashlib, algo_name):
            hasher = getattr(hashlib, algo_name)(data)
            expected = hasher.hexdigest()
        else:
            expected = hashlib.new(algo_name, data).hexdigest()
    else:  # algo_type == 'new'
        assert algo_name is not None, "hashlib.new used with non-constant algorithm name; cannot compute expected digest"
        expected = hashlib.new(algo_name, data).hexdigest()

    # validate_d145ac should return True for the correct hexdigest
    assert validate_d145ac(data, expected) is True
    # and False for an incorrect hexdigest (flip last hex nibble)
    altered = expected[:-1] + ('0' if expected[-1] != '0' else '1')
    assert validate_d145ac(data, altered) is False

