from pathlib import Path

def _load_target_function():
    # Find a .py file in the current directory that defines retrieve_encryption_keys
    for p in Path('.').glob('*.py'):
        if p.name.startswith('test_'):
            continue
        try:
            text = p.read_text(encoding='utf-8')
        except Exception:
            continue
        if 'def retrieve_encryption_keys' in text:
            module_name = p.stem
            module = importlib.import_module(module_name)
            func = getattr(module, 'retrieve_encryption_keys', None)
            if callable(func):
                return func
    raise ImportError("Could not find function retrieve_encryption_keys in any local .py file")

def _get_requests_get_calls(func):
    src = inspect.getsource(func)
    tree = ast.parse(src)
    calls = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            func_node = node.func
            # requests.get(...)
            if isinstance(func_node, ast.Attribute) and isinstance(func_node.value, ast.Name):
                if func_node.value.id == 'requests' and func_node.attr == 'get':
                    calls.append(node)
            # direct get(...) after `from requests import get`
            if isinstance(func_node, ast.Name) and func_node.id == 'get':
                # best-effort include: consider it a requests.get call
                calls.append(node)
    return calls

def _constant_string_from_node(node):
    # Return string if node is a constant string or f-string parts concatenated, else None
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    if isinstance(node, ast.JoinedStr):
        parts = []
        for value in node.values:
            if isinstance(value, ast.Constant) and isinstance(value.value, str):
                parts.append(value.value)
            else:
                parts.append('{}')
        return ''.join(parts)
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add,)):
        left = _constant_string_from_node(node.left)
        right = _constant_string_from_node(node.right)
        if left is not None and right is not None:
            return left + right
    return None

