def test_requests_get_verify_not_false():
    func = _load_target_function()
    calls = _get_requests_get_calls(func)
    assert calls, "No requests.get calls found in function; unable to validate transport security"
    for call in calls:
        for kw in call.keywords:
            if kw.arg == 'verify':
                # If verify is the literal False -> vulnerable
                if isinstance(kw.value, ast.Constant) and kw.value.value is False:
                    raise AssertionError("requests.get called with verify=False (insecure TLS verification)")

def test_requests_get_url_scheme_and_cert_or_verify():
    func = _load_target_function()
    calls = _get_requests_get_calls(func)
    assert calls, "No requests.get calls found in function; unable to validate transport security"
    for call in calls:
        # Check first positional argument for plain http
        if call.args:
            first_arg = call.args[0]
            s = _constant_string_from_node(first_arg)
            if s is not None:
                if s.lstrip().startswith('http://'):
                    raise AssertionError("requests.get called with a plain http:// URL (cleartext transmission)")

        # Ensure verify is not explicitly False (covered above) and prefer presence of cert or explicit verify True
        has_cert = any(kw.arg == 'cert' for kw in call.keywords)
        verify_kw = next((kw for kw in call.keywords if kw.arg == 'verify'), None)
        if verify_kw is None:
            # no explicit verify -> default is secure (requests verifies by default)
            continue
        # if verify provided, ensure it's not False
        if isinstance(verify_kw.value, ast.Constant) and verify_kw.value.value is True:
            continue
        # if verify is some non-literal expression, we cannot be sure; require cert to be present as a fallback
        if not has_cert:
            raise AssertionError("requests.get uses non-constant or non-True 'verify' without client cert; potential insecure transport")

