            func_node = node.func
            if isinstance(func_node, ast.Attribute) and isinstance(func_node.value, ast.Name) and func_node.value.id == 'hashlib' and func_node.attr == 'pbkdf2_hmac':
                found = True
                # check first arg is 'sha256'
                if not node.args:
                    raise AssertionError("pbkdf2_hmac called without arguments")
                alg_node = node.args[0]
                if isinstance(alg_node, ast.Constant):
                    alg_val = alg_node.value
                elif isinstance(alg_node, ast.Str):  # Python <3.8
                    alg_val = alg_node.s
                else:
                    alg_val = None
                assert isinstance(alg_val, str), "pbkdf2_hmac algorithm argument must be a string literal"
                assert alg_val.lower() == 'sha256', f"pbkdf2_hmac must use sha256 (found {alg_val})"

                # check iterations (4th positional arg) if present
                if len(node.args) >= 4:
                    iter_node = node.args[3]
                    if isinstance(iter_node, ast.Constant) and isinstance(iter_node.value, int):
