                    elif isinstance(iter_node, ast.Num):  # older AST
                        iterations = iter_node.n
                    else:
                        iterations = None
                    assert isinstance(iterations, int) and iterations >= 100000, f"pbkdf2_hmac iterations must be >= 100000 (found {iterations})"
                else:
                    # iterations might be passed as a keyword; check keywords
                    iter_val = None
                    for kw in node.keywords:
                        if kw.arg == 'iterations' or kw.arg == 'iters' or kw.arg == 'count':
                            v = kw.value
                            if isinstance(v, ast.Constant) and isinstance(v.value, int):
                                iter_val = v.value
                            elif isinstance(v, ast.Num):
                                iter_val = v.n
                    assert isinstance(iter_val, int) and iter_val >= 100000, "pbkdf2_hmac iterations argument must be present and >= 100000"
    assert found, "hashlib.pbkdf2_hmac call not found in secure_passphrase_digest implementation"

