    func = _find_secure_passphrase_digest()
    tree = _parse_source_tree(func)

    found_good_generator = False
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            # Detect os.urandom(<n>) or secrets.token_bytes(<n>)
            func_node = node.func
            if isinstance(func_node, ast.Attribute) and isinstance(func_node.value, ast.Name):
                modname = func_node.value.id
                fname = func_node.attr
                if (modname == 'os' and fname == 'urandom') or (modname == 'secrets' and fname in ('token_bytes', 'token_hex')):
                    # check length argument
                    if node.args:
                        arg = node.args[0]
                        if isinstance(arg, ast.Constant) and isinstance(arg.value, int):
                            length = arg.value
                        elif isinstance(arg, ast.Num):
                            length = arg.n
                        else:
                            length = None
                        if isinstance(length, int) and length >= 16:
                            found_good_generator = True
                            break
    if found_good_generator:
        return  # passes

    # Fallback runtime checks: ensure returned salt is hex of at least 16 bytes and is random per invocation
    r1 = func("testpassphrase")
