    salt1, _ = _extract_return_parts(r1)
    salt2, _ = _extract_return_parts(r2)
    # salt hex length must represent at least 16 bytes (32 hex chars)
    assert len(salt1) >= 32, "Salt length too small; must be at least 16 raw bytes (32 hex chars)"
    assert salt1 != salt2, "Salt appears to be constant/deterministic; must be randomly generated per invocation"

def test_result_not_equal_to_simple_hashes():
    func = _find_secure_passphrase_digest()
