        hashlib.sha224(pw.encode()).hexdigest(),
        hashlib.sha256(pw.encode()).hexdigest(),
        hashlib.sha384(pw.encode()).hexdigest(),
        hashlib.sha512(pw.encode()).hexdigest(),
