    raise RuntimeError(f"Entrypoint function '{entry_name}' not found in loaded modules")

def _analyze_source_for_insecure_verify(source):
    tree = ast.parse(source)

    # collect simple module-level name -> boolean constants (e.g., INSECURE=False)
    name_bool_map = {}
    for node in tree.body:
        if isinstance(node, ast.Assign):
            # only handle simple single-target name assignments
            if len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
                target = node.targets[0].id
                val = node.value
                if isinstance(val, ast.Constant) and isinstance(val.value, bool):
                    name_bool_map[target] = val.value

    insecure_instances = []

    class VerifyVisitor(ast.NodeVisitor):
        def visit_Call(self, node):
            # Check keyword verify explicitly set to False or to a name that maps to False
            for kw in getattr(node, "keywords", []):
                if kw.arg == "verify":
                    val = kw.value
                    if isinstance(val, ast.Constant) and val.value is False:
                        insecure_instances.append(("verify_kw_false", node.lineno, ast.unparse(node.func) if hasattr(ast, "unparse") else None))
                    elif isinstance(val, ast.Name) and val.id in name_bool_map and name_bool_map[val.id] is False:
                        insecure_instances.append(("verify_kw_false_via_name", node.lineno, val.id))

            # Detect positional passing of False to common SSL-using calls like requests.get(url, False)
            # We look for calls where the function name is 'get' or 'Session' and the second positional arg is False
            func_name = None
            if isinstance(node.func, ast.Attribute):
                func_name = node.func.attr
                # also capture requests.Session(...) pattern as a constructor
                if func_name == "Session":
                    for kw in getattr(node, "keywords", []):
                        if kw.arg == "verify":
                            val = kw.value
                            if isinstance(val, ast.Constant) and val.value is False:
                                insecure_instances.append(("session_verify_false", node.lineno, ast.unparse(node.func) if hasattr(ast, "unparse") else None))
                            elif isinstance(val, ast.Name) and val.id in name_bool_map and name_bool_map[val.id] is False:
                                insecure_instances.append(("session_verify_false_via_name", node.lineno, val.id))
            elif isinstance(node.func, ast.Name):
                func_name = node.func.id

            # positional check: second arg equals False (common pattern requests.get(url, verify))
            if func_name in ("get", "request", "Session"):
