                    second = node.args[1]
                    if isinstance(second, ast.Constant) and second.value is False:
                        insecure_instances.append(("verify_positional_false", node.lineno, func_name))
                    elif isinstance(second, ast.Name) and second.id in name_bool_map and name_bool_map[second.id] is False:
                        insecure_instances.append(("verify_positional_false_via_name", node.lineno, second.id))

            self.generic_visit(node)

        def visit_Assign(self, node):
            # detect assignments like s.verify = False
            for target in node.targets:
                if isinstance(target, ast.Attribute) and target.attr == "verify":
                    val = node.value
                    if isinstance(val, ast.Constant) and val.value is False:
                        insecure_instances.append(("attr_verify_assign_false", node.lineno, ast.unparse(target) if hasattr(ast, "unparse") else None))
                    elif isinstance(val, ast.Name) and val.id in name_bool_map and name_bool_map[val.id] is False:
                        insecure_instances.append(("attr_verify_assign_false_via_name", node.lineno, val.id))
            self.generic_visit(node)

    VerifyVisitor().visit(tree)
    return insecure_instances

