KEYWORDS = ('key', 'token', 'secret', 'password')
THIS_TEST_FILENAME = Path(__file__).name

def _iter_source_files():
    for path in Path('.').rglob('*.py'):
        if path.name.startswith('test_'):
            # skip other test files
            continue
        if path.name == THIS_TEST_FILENAME:
            continue
        yield path

def _const_str_value(node):
    # Compatible with different Python AST node types
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    if isinstance(node, ast.Str):  # older AST node
        return node.s
    return None

def _get_target_names(target):
    # Return a list of simple names for an assignment target (Name or Attribute)
    names = []
    if isinstance(target, ast.Name):
        names.append(target.id)
    elif isinstance(target, ast.Attribute):
        names.append(target.attr)
    elif isinstance(target, ast.Tuple) or isinstance(target, ast.List):
        for elt in target.elts:
            names.extend(_get_target_names(elt))
    return names

