    if not name:
        return False
    lname = name.lower()
    return any(k in lname for k in KEYWORDS)

def _is_authorization_key(node):
    # node can be ast.Constant/ast.Str or ast.Name etc.
    val = _const_str_value(node)
    if val is None:
        return False
    return val.strip().lower() == 'authorization' or val.strip().lower().startswith('authorization')

def _dict_has_hardcoded_secret(dnode):
    # check dict values for hard-coded string secrets for Authorization or generic secrets
    if not isinstance(dnode, ast.Dict):
        return False, None
    for k, v in zip(dnode.keys, dnode.values):
        vstr = _const_str_value(v)
        if vstr is None:
            continue
