        if _is_authorization_key(k):
            return True, f"Authorization header with hardcoded value: {vstr!r}"
        # If the value is assigned to something that looks like a secret (contains token/secret/password or looks long)
        if len(vstr) >= 8:
            # long string literals used as values are likely secrets
            return True, f"Likely hardcoded credential value: {vstr!r}"
        # small heuristic: values that include 'bearer ' directly are suspicious even if short
        if 'bearer ' in vstr.lower():
