    target_func = None
    for m in list(sys.modules.values()):
        if not m:
            continue
        if hasattr(m, 'fetch_credentials_v2'):
            target_func = getattr(m, 'fetch_credentials_v2')
            break
    if target_func is None:
        for path in glob.glob('*.py'):
            name = os.path.basename(path)
            if name.startswith('test_') or name == '__init__.py':
                continue
            loader = importlib.machinery.SourceFileLoader(f"scan_{name}", path)
            spec = importlib.util.spec_from_loader(loader.name, loader)
            mod = importlib.util.module_from_spec(spec)
            try:
                loader.exec_module(mod)
            except Exception:
                continue
            if hasattr(mod, 'fetch_credentials_v2'):
                target_func = getattr(mod, 'fetch_credentials_v2')
                break
    assert target_func is not None, "fetch_credentials_v2 not found in project files"
    src = inspect.getsource(target_func)
    tree = ast.parse(src)
    func_node = None
    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and node.name == target_func.__name__:
            func_node = node
            break
    assert func_node is not None, "Could not parse function AST"
    found_requests_get = False
    verify_value = None
    for stmt in ast.walk(func_node):
        if isinstance(stmt, ast.Call):
            func = stmt.func
            if isinstance(func, ast.Attribute) and getattr(func.value, 'id', None) == 'requests' and func.attr == 'get':
                found_requests_get = True
                # inspect keywords
                for kw in stmt.keywords:
                    if kw.arg == 'verify':
                        # handle different AST versions
                        if isinstance(kw.value, ast.Constant):
                            verify_value = kw.value.value
                        elif hasattr(ast, 'NameConstant') and isinstance(kw.value, ast.NameConstant):
                            verify_value = kw.value.value
                        elif isinstance(kw.value, ast.Name):
                            # value is a name; cannot be sure it's True -> treat as not explicitly True
                            verify_value = None
                        else:
                            verify_value = None
                # stop at first requests.get found
                break
    assert found_requests_get, "No call to requests.get found in function"
    assert verify_value is True, "requests.get called without verify=True (TLS verification disabled or omitted)"

