def test_query_does_not_include_raw_input():
    import sys, inspect
    # find the authenticate_user function and its module
    func = None
    mod = None
    for m in list(sys.modules.values()):
        if not m:
            continue
        if hasattr(m, "authenticate_user"):
            candidate = getattr(m, "authenticate_user")
            if inspect.isfunction(candidate):
                func = candidate
                mod = m
                break
    if func is None:
        raise RuntimeError("authenticate_user not found in loaded modules")

    # stub DB to capture execute calls
    class DummyDB:
        def __init__(self):
            self.called = False
            self.args = None
            self.kwargs = None
        def execute(self, *args, **kwargs):
            self.called = True
            self.args = args
            self.kwargs = kwargs
            return "OK"

    dummy = DummyDB()
    # preserve original db if present
    original_db = getattr(mod, "db", None)
    try:
        mod.db = dummy
        # use a distinctive injection-like payload
        payload = "INJ_PAYLOAD_123' OR '1'='1"
        func(payload, "irrelevant_password")
        assert dummy.called, "authenticate_user did not call db.execute"
        # ensure the raw payload was not embedded into the SQL string
        assert len(dummy.args) >= 1, "db.execute called without a query argument"
        query = dummy.args[0] or ""
        assert payload not in query, "Potential SQL injection: user input found directly in query string"
    finally:
        # restore original db
        if original_db is None:
            try:
                delattr(mod, "db")
            except Exception:
                pass
        else:
            mod.db = original_db


