        username = "user_for_test"
        password = "pass_for_test"
        func(username, password)
        assert dummy.called, "authenticate_user did not call db.execute"
        # expect parameters to be passed separately (positional second arg or kwargs)
        if len(dummy.args) >= 2:
            params = dummy.args[1]
            assert isinstance(params, (tuple, list, dict)), "Expected parameters to be passed separately to db.execute"
            if isinstance(params, (tuple, list)):
                assert len(params) >= 2 and params[0] == username and params[1] == password, "Parameters do not match username/password"
            else:  # dict
                # common named placeholder keys could be 'username' and 'password'
                assert ("username" in params and "password" in params and params["username"] == username and params["password"] == password) \
                       or (next(iter(params.values()), None) == username), "Named parameters do not contain username/password as expected"
        elif "params" in dummy.kwargs or "parameters" in dummy.kwargs:
            params = dummy.kwargs.get("params") or dummy.kwargs.get("parameters")
