        else:
            # execute called with only a single argument (the query) -> likely vulnerable
            assert False, "db.execute was called with a single interpolated query argument; parameters should be provided separately"
    finally:
        # restore original db
        if original_db is None:
            try:
                delattr(mod, "db")
            except Exception:
                pass
        else:
            mod.db = original_db

