def test_no_hardcoded_credentials_in_connect_call():
    import sys, inspect, ast
    # find the connect_to_db function and its defining module
    func = None
    module = None
    for mod in list(sys.modules.values()):
        if not mod:
            continue
        if hasattr(mod, "connect_to_db"):
            candidate = getattr(mod, "connect_to_db")
            if inspect.isfunction(candidate):
                func = candidate
                module = mod
                break
    assert func is not None, "connect_to_db function not found in loaded modules"

    src = inspect.getsource(func)
    func_ast = ast.parse(src)

    cred_keywords = {"password", "passwd", "user", "username"}
    found_hardcoded = []

    def is_str_constant(node):
        return isinstance(node, ast.Constant) and isinstance(node.value, str) or isinstance(node, ast.Str)

    # Walk the function AST and find calls to mysql.connect
    for node in ast.walk(func_ast):
        if isinstance(node, ast.Call):
            # detect mysql.connect(...) style
            func_node = node.func
            is_mysql_connect = False
            if isinstance(func_node, ast.Attribute) and func_node.attr == "connect":
                # check that receiver is named "mysql" (simple heuristic)
                if isinstance(func_node.value, ast.Name) and func_node.value.id == "mysql":
                    is_mysql_connect = True
            if not is_mysql_connect:
                continue
            # examine keyword arguments
            for kw in node.keywords:
                if kw.arg and kw.arg.lower() in cred_keywords:
                    # if value is a string literal -> hardcoded credential
                    if is_str_constant(kw.value):
                        found_hardcoded.append((kw.arg, getattr(kw.value, "s", getattr(kw.value, "value", None))))
                    # if value is a Name, we'll catch assignment in another test, but also consider as suspicious here if it's a literal in the function scope
    assert not found_hardcoded, f"Hardcoded credential literals passed to mysql.connect detected: {found_hardcoded}"


