    import pytest
    from solution import process_upload_v3, MAX_SIZE

    class MockStream:
        def __init__(self, data=None):
            self.data = data
            self.read_calls = []

        def read(self, size=None):
            # Record the size argument
            self.read_calls.append(size)
            # If called without a size, treat as unbounded read attempt -> fail fast
            if size is None:
                raise RuntimeError("Unbounded read detected")
            # If caller asks for more than MAX_SIZE, return MAX_SIZE+1 bytes to trigger rejection
