import ast
import glob
import os

def _find_function_ast(func_name):
    for path in glob.glob("*.py"):
        if os.path.basename(path).startswith("test_"):
            continue
        try:
            with open(path, "r", encoding="utf-8") as f:
                src = f.read()
        except (IOError, OSError):
            continue
        try:
            mod = ast.parse(src)
        except SyntaxError:
            continue
        for node in mod.body:
            if isinstance(node, ast.FunctionDef) and node.name == func_name:
                return node
    raise RuntimeError(f"Function {func_name} not found in any .py file in the current directory")

def _const_str_value(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return node.value
    if isinstance(node, ast.Str):
        return node.s
    return None

def _call_is_hashlib_attr(call_node, attr_name):
    func = call_node.func
    return isinstance(func, ast.Attribute) and isinstance(func.value, ast.Name) and func.value.id == "hashlib" and func.attr == attr_name

def _call_is_name(call_node, name):
    func = call_node.func
    return isinstance(func, ast.Name) and func.id == name

def _call_is_hashlib_new_with_weak(call_node, weak_names):
    func = call_node.func
    if isinstance(func, ast.Attribute) and isinstance(func.value, ast.Name) and func.value.id == "hashlib" and func.attr == "new":
        if call_node.args:
            s = _const_str_value(call_node.args[0])
            if s and s.lower() in weak_names:
                return True
    return False

def _collect_weak_hash_usages(func_node, weak_names=("md5", "sha1")):
    violations = []
    for n in ast.walk(func_node):
        if isinstance(n, ast.Call):
            # hashlib.md5(...) or hashlib.sha1(...)
            for name in weak_names:
                if _call_is_hashlib_attr(n, name):
                    violations.append(f"hashlib.{name}")
            # direct md5(...) if imported as from hashlib import md5
            for name in weak_names:
                if _call_is_name(n, name):
                    violations.append(name)
            # hashlib.new("md5", ...)
            if _call_is_hashlib_new_with_weak(n, set(weak_names)):
                s = _const_str_value(n.args[0])
                violations.append(f"hashlib.new({s})")
    return violations

def _detect_strong_hash(func_node, strong_names=None):
    if strong_names is None:
        strong_names = {
            "sha256", "sha384", "sha512",
            "sha3_256", "sha3_384", "sha3_512",
            "blake2b", "blake2s"
        }
    for n in ast.walk(func_node):
        if isinstance(n, ast.Call):
            # hashlib.sha256(...)
            func = n.func
            if isinstance(func, ast.Attribute) and isinstance(func.value, ast.Name) and func.value.id == "hashlib":
                if func.attr in strong_names:
                    return True
                if func.attr == "new":
                    if n.args:
                        s = _const_str_value(n.args[0])
                        if s and s.lower() in strong_names:
                            return True
            # direct sha256(...) if imported as from hashlib import sha256
            if isinstance(func, ast.Name) and func.id in strong_names:
                return True
    return False

