def _find_module_with_attr(attr_name):
    for mod in list(sys.modules.values()):
        try:
            if mod and hasattr(mod, attr_name):
                return mod
        except Exception:
            continue
    raise RuntimeError(f"Module with attribute {attr_name!r} not found")

def _reset_message_database(module):
    # Ensure tests start from a known state
    if hasattr(module, "message_database"):
        module.message_database = {'users': {'1': {'email': 'old.email@example.com'}}}

def _get_email(module, user_id='1'):
    db = getattr(module, "message_database", None)
    if not db:
        return None
    return db['users'].get(user_id, {}).get('email')

def _build_request(headers=None, body=None):
    return {
        'headers': headers or {},
        'body': body or {}
    }

def test_requires_csrf_header():
    """
    The endpoint must reject requests that do not include a valid CSRF header.
    This will fail if the implementation does not check for a CSRF token at all.
    """
    module = _find_module_with_attr("change_message_email")
    change_fn = getattr(module, "change_message_email")
    _reset_message_database(module)

    req = _build_request(headers={}, body={'user_id': '1', 'new_email': 'attacker@example.com'})
    result = change_fn(req)

    # Should be rejected
    assert result is False, "Request without CSRF header was accepted (possible CSRF vulnerability)"
    # Ensure data was not changed
    assert _get_email(module, '1') == 'old.email@example.com'

def test_rejects_csrf_token_in_body():
    """
    A secure implementation should require the CSRF token from the protected location (e.g., a header),
    and not accept it solely from body fields that an attacker could control in a cross-site POST.
    This test fails if the application accepts a CSRF token supplied in the request body instead of a protected header.
    """
    module = _find_module_with_attr("change_message_email")
    change_fn = getattr(module, "change_message_email")
    _reset_message_database(module)

    # Put what might look like a token in the body (attacker-controlled)
    req = _build_request(headers={}, body={'user_id': '1', 'new_email': 'attacker@example.com', 'X-CSRF-Token': 'secure_csrf_token'})
    result = change_fn(req)

    # Should be rejected because header was not used
    assert result is False, "Request with CSRF token in body was accepted (token location not enforced)"
    assert _get_email(module, '1') == 'old.email@example.com'

def test_no_hardcoded_csrf_token_literal():
    """
    Detects implementations that use a hard-coded CSRF token literal in source (predictable token).
    A secure implementation should not embed a fixed string literal for the CSRF token named VALID_CSRF_Msg_token.
    This test fails on implementations where VALID_CSRF_Msg_token is assigned a string literal in source code.
    """
    module = _find_module_with_attr("change_message_email")
    try:
        src = inspect.getsource(module)
    except (OSError, TypeError):
        pytest.skip("Cannot retrieve source for the module under test")

    tree = ast.parse(src)
    found_hardcoded = False

    for node in ast.walk(tree):
        # Look for assignments like: VALID_CSRF_Msg_token = "some_string"
        if isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id == "VALID_CSRF_Msg_token":
                    # Depending on Python version AST node for string literal may be ast.Constant or ast.Str
                    val = node.value
                    if isinstance(val, ast.Constant) and isinstance(val.value, str):
                        found_hardcoded = True
                    elif isinstance(val, ast.Str):
                        found_hardcoded = True

        # Also check for simple AnnAssign (variable: type = "...")
        if isinstance(node, ast.AnnAssign):
            target = node.target
            if isinstance(target, ast.Name) and target.id == "VALID_CSRF_Msg_token":
                val = node.value
                if isinstance(val, ast.Constant) and isinstance(val.value, str):
                    found_hardcoded = True
                elif isinstance(val, ast.Str):
