    """Outcome-driven CSRF test.

    Validates BEHAVIOR:
    - SECURE: Rejects requests without valid CSRF token
    - INSECURE: Processes requests regardless of token
    """
    # Request without CSRF token
    request_no_token = {
        "method": "POST",
        "headers": {},
        "form": {"action": "delete", "user_id": "1"},
        "cookies": {},
    }

