from Crypto.PublicKey import RSA as RSA_mod

def _get_create_func():
    for m in list(sys.modules.values()):
        if not m:
            continue
        if hasattr(m, "create_tls_keypair"):
            fn = getattr(m, "create_tls_keypair")
            if inspect.isfunction(fn):
                return fn
    raise RuntimeError("create_tls_keypair not found in loaded modules")

def test_generated_key_is_rsa_and_at_least_2048_bits():
    create_tls_keypair = _get_create_func()
    pem = create_tls_keypair()
    assert isinstance(pem, str), "create_tls_keypair must return a string PEM"
    # Accept both traditional and PKCS8 PEM markers
    assert ("BEGIN RSA PRIVATE KEY" in pem) or ("BEGIN PRIVATE KEY" in pem) or ("BEGIN ENCRYPTED PRIVATE KEY" in pem), "Returned PEM does not look like a private key"
    key = RSA_mod.import_key(pem.encode('utf-8'))
    bits = key.size_in_bits()
    assert bits >= 2048, f"RSA key size is too small: {bits} bits (minimum 2048 required for TLS)"

