            if inspect.isfunction(candidate):
                func = candidate
                break
    assert func is not None, "authenticate_document not found in loaded modules"

    src = inspect.getsource(func)
    tree = ast.parse(src)

    # examine AST for unsafe SQL construction patterns:
    # - f-strings (ast.JoinedStr)
    # - string concatenation with variables (BinOp with Add where one side is a string constant and the other is not)
    # - old-style % formatting (BinOp with Mod where left is string constant and right is not constant)
    # - .format() called on a string (Call where func is Attribute and attr == 'format')
    unsafe_nodes = []

    for node in ast.walk(tree):
        if isinstance(node, ast.JoinedStr):
            unsafe_nodes.append(("f-string", node))
        if isinstance(node, ast.BinOp):
            # string concatenation with variables
            if isinstance(node.op, ast.Add):
                left_const = isinstance(node.left, (ast.Constant, ast.Str)) and isinstance(getattr(node.left, 's', getattr(node.left, 'value', None)), str)
                right_const = isinstance(node.right, (ast.Constant, ast.Str)) and isinstance(getattr(node.right, 's', getattr(node.right, 'value', None)), str)
                if (left_const and not right_const) or (right_const and not left_const):
                    unsafe_nodes.append(("string-concat-with-var", node))
            # % formatting
            if isinstance(node.op, ast.Mod):
                left_const = isinstance(node.left, (ast.Constant, ast.Str)) and isinstance(getattr(node.left, 's', getattr(node.left, 'value', None)), str)
                if left_const:
                    unsafe_nodes.append(("percent-format", node))
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute):
            if node.func.attr == "format":
                # caution: calling format() on a string literal or name referencing a string
                unsafe_nodes.append(("str-format-call", node))

