def test_allows_small_upload_and_uses_bounded_read():
    # This test ensures the implementation calls read with an explicit size (no unbounded read)
    # and correctly returns small uploads.
    MAX = process_upload_v2.__globals__['MAX_SIZE']
    data = b'hello-world'

    class BoundedStream:
        def __init__(self, data):
            self.data = data
            self.read_calls = []

        def read(self, size=-1):
            self.read_calls.append(size)
            # Simulate refusing unbounded reads (vulnerable implementations that call read() with no size will trigger an error)
            if size == -1:
                raise RuntimeError("unbounded read not allowed")
            # Return up to requested size
            if size >= len(self.data):
                return self.data
            return self.data[:size]

    stream = BoundedStream(data)
    result = process_upload_v2(stream)
    assert result == data
    # Ensure the code requested a bounded read (an integer size >= 0 was used)
    assert any(isinstance(sz, int) and sz >= 0 for sz in stream.read_calls)


